    r0, r1 = min(r for r, c in magenta), max(r for r, c in magenta)
    c0, c1 = min(c for r, c in magenta), max(c for r, c in magenta)
    orange_r = sum(r for r, c in orange) / len(orange)
    orange_c = sum(c for r, c in orange) / len(orange)
    for r, c in orange:
        out[r][c] = 6
    for r, c in magenta:
        out[r][c] = 7
    if orange_c < c0:
        for c in sorted({c for r, c in zeros if c < c0}):
            for r in range(r0, r1 + 1):
                out[r][c] = 2
    elif orange_c > c1:
        for c in sorted({c for r, c in zeros if c > c1}):
            for r in range(r0, r1 + 1):
                out[r][c] = 2
    elif orange_r < r0:
        for r in sorted({r for r, c in zeros if r < r0}):
            for c in range(c0, c1 + 1):
                out[r][c] = 2
    else:
        for r in sorted({r for r, c in zeros if r > r1}):
            for c in range(c0, c1 + 1):
